import re

input_file = '/home/andrea-zabala-c/.gemini/antigravity-ide/brain/d8f95f8d-fe86-4b54-9176-71f893afdc24/bitacora_chat_ia_dia_a_dia.md'
output_file = '/home/andrea-zabala-c/.gemini/antigravity-ide/brain/d8f95f8d-fe86-4b54-9176-71f893afdc24/analisis_forense_logs_ia.md'

with open(input_file, 'r', encoding='utf-8') as f:
    lines = f.readlines()

current_date = ""
summary = {}
capture_next = 0

for line in lines:
    date_match = re.match(r'## 📅 (\d{4}-\d{2}-\d{2}) - (.*)', line)
    if date_match:
        current_date = date_match.group(1)
        title = date_match.group(2)
        if current_date not in summary:
            summary[current_date] = []
        summary[current_date].append(f"\n### 📌 Tema: {title}\n")
        continue

    if current_date:
        # Extract tables, bullet points with checkmarks, and critical cybersecurity keywords
        is_critical = False
        if "|" in line and "-" not in line:  # Table rows (skip separator)
            is_critical = True
        elif any(icon in line for icon in ["✅", "❌", "⚠️", "🚨", "📌"]):
            is_critical = True
        elif re.search(r'(ataque|DPI|intercept|vpn|rootkit|MAC|ip exposed|censura|borrado|planchado|blanco|QR|hash|sha256|spoofing|live stream)', line, re.IGNORECASE):
            is_critical = True

        if is_critical and line.strip() and not line.strip().startswith("> ..."):
            if not summary[current_date] or summary[current_date][-1] != line:
                summary[current_date].append(line.replace("> ", ""))

with open(output_file, 'w', encoding='utf-8') as f:
    f.write("# 🕵️ Análisis Forense Detallado de Bitácoras IA (Día a Día)\n\n")
    f.write("> **Extracción automatizada de hallazgos periciales y eventos de seguridad críticos**\n\n")
    for date in sorted(summary.keys()):
        f.write(f"## 📅 Fecha Crítica: {date}\n")
        # Remove duplicates while preserving order
        seen = set()
        for l in summary[date]:
            if l not in seen:
                f.write(l)
                seen.add(l)
        f.write("\n\n---\n")

print("Analysis extraction complete.")

import json
from datetime import datetime
import sys

def parse_logs(input_file, output_file):
    try:
        with open(input_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error loading JSON: {e}")
        return

    convs = []
    for conv in data:
        title = conv.get('title', 'Sin Título')
        mapping = conv.get('mapping', {})

        messages = []
        for k, v in mapping.items():
            if not isinstance(v, dict): continue
            msg = v.get('message')
            if msg:
                date_str = msg.get('inserted_at')
                role = msg.get('model', 'user') if 'model' in msg else 'user'

                content = ""
                if 'content' in msg and 'parts' in msg['content']:
                    parts = [str(p) for p in msg['content']['parts'] if p is not None]
                    content = "".join(parts)

                if not content and 'fragments' in msg:
                    for frag in msg['fragments']:
                        if isinstance(frag, dict) and 'content' in frag:
                            content += frag['content'] + "\n"
                        elif isinstance(frag, dict) and 'text' in frag:
                            content += frag['text'] + "\n"
                        elif isinstance(frag, dict) and 'files' in frag:
                            content += f"[Archivos adjuntos: {len(frag['files'])}]\n"

                if not content and 'content' in msg and isinstance(msg['content'], str):
                    content = msg['content']

                if date_str and content.strip():
                    try:
                        dt = datetime.fromisoformat(date_str.replace('Z', '+00:00'))
                        messages.append({'date': dt, 'role': role, 'content': content.strip()})
                    except Exception as e:
                        pass

        if messages:
            messages.sort(key=lambda x: x['date'])
            start_date = messages[0]['date']
            convs.append({'title': title, 'start_date': start_date, 'messages': messages})

    convs.sort(key=lambda x: x['start_date'])

    with open(output_file, 'w', encoding='utf-8') as f:
        f.write(f"# 🤖 Bitácora Forense: {input_file.split('/')[-1]}\n\n")

        for conv in convs:
            date_str = conv['start_date'].strftime("%Y-%m-%d")
            f.write(f"## 📅 {date_str} - {conv['title']}\n\n")

            for msg in conv['messages']:
                role = "🧑‍💻 Especialista (Andrea)" if msg['role'] == "user" else "🤖 Asistente IA"
                msg_date = msg['date'].strftime("%H:%M:%S")
                f.write(f"**{role}** ({msg_date}):\n")

                text = msg['content']
                if len(text) > 1500:
                    text = text[:1500] + "\n\n... `[Texto extenso truncado para preservar legibilidad en el reporte. Longitud original: " + str(len(text)) + " caracteres]`"

                formatted_text = "\n".join([f"> {line}" for line in text.split('\n')])
                f.write(f"{formatted_text}\n\n")

            f.write("---\n\n")

    print(f"Artifact generated successfully at {output_file}")

if __name__ == '__main__':
    parse_logs(sys.argv[1], sys.argv[2])

